import { fileURLToPath } from 'node:url'

import { migrate } from 'drizzle-orm/node-sqlite/migrator'

import type { Database } from './connection.ts'

/** `server/drizzle/`, generated by drizzle-kit. Three folders up from both `src/` and `dist/` builds of this module. */
export const MIGRATIONS_FOLDER = fileURLToPath(new URL('../../../drizzle', import.meta.url))

/**
 * Applies every pending migration, in order, in one transaction. Migrations already applied are
 * recorded in `__drizzle_migrations` and skipped, so running this again changes nothing. If any
 * migration fails, all of them are rolled back and an error is thrown: the caller must stop.
 */
export function applyMigrations(db: Database, migrationsFolder: string = MIGRATIONS_FOLDER): void {
  try {
    migrate(db, { migrationsFolder })
  } catch (error) {
    throw new Error(`Database migration failed; no migration was applied. ${rootMessage(error)}`, { cause: error })
  }
}

/** The innermost cause's message: SQLite's own reason, rather than Drizzle's "Failed query" wrapper. */
function rootMessage(error: unknown): string {
  let current = error
  while (current instanceof Error && current.cause !== undefined) current = current.cause
  return current instanceof Error ? current.message : String(current)
}
